#!/usr/bin/env bash
# Make Ravana Dark the default KDE color scheme for new users.
# Color schemes themselves are in system_files/usr/share/color-schemes/
# (generated by tools/gen-kde-colors.py).
set -euxo pipefail

test -f /usr/share/color-schemes/RavanaDark.colors
test -f /usr/share/color-schemes/RavanaLight.colors

# Show what the base ships, so overrides are visible in the build log.
grep -E '^(\[|LookAndFeelPackage|ColorScheme|AccentColor)' /etc/xdg/kdeglobals || true
LNF="$(sed -n 's/^LookAndFeelPackage=//p' /etc/xdg/kdeglobals | head -1)"
for d in /usr/share/plasma/look-and-feel/"${LNF:-none}"/contents/defaults; do
    [ -f "$d" ] && grep -nE '^\[|ColorScheme' "$d" || true
done

KW="$(command -v kwriteconfig6 || command -v kwriteconfig5)"
"$KW" --file /etc/xdg/kdeglobals --group General --key ColorScheme RavanaDark

# Look-and-feel packages carry their own default color scheme; point the active
# one at Ravana Dark too, so "Global Theme" defaults agree with kdeglobals.
if [ -n "$LNF" ] && [ -f "/usr/share/plasma/look-and-feel/$LNF/contents/defaults" ]; then
    "$KW" --file "/usr/share/plasma/look-and-feel/$LNF/contents/defaults" \
        --group kdeglobals --group General --key ColorScheme RavanaDark
fi

grep -A3 '^\[General\]' /etc/xdg/kdeglobals
